// Why Code: this is a test stand-in. One place holds every pretend rule (chosen mostly from the tenant's name), which would otherwise need a large Switch and one Set node per branch. It never throws: any error becomes a "failed" result.
const input = $('Case from the Dispatcher').first().json;
const s = input.settings || {};
const c = $('Claim the case').first().json;
const lead = $input.first().json || {};

const TEXT = {
  DATES_INVALID: 'The dates on the spreadsheet row are wrong or missing',
  DEATH_REFERRED: 'The tenancy ended because the tenant died; these are passed to staff',
  CHANGE_REASON_NOT_VALID: 'The reason for the change is not one the automation handles',
  SAME_TENANCY_AS_EARLIER_ROW: 'Covered by an earlier row for the same tenancy',
  EARLIER_ROW_NOT_COMPLETED: 'The earlier row for this tenancy was not completed, so this person was not added',
  ADDRESS_NOT_FOUND: 'The account could not be found in RBIS',
  UNABLE_TO_ADD_PARTY: 'A person could not be added to the account',
  NO_CONTACT_DETAILS: 'Liability started, but there were no contact details to record',
  RBIS_ERROR: 'RBIS did not respond or returned an error',
};
const norm = (x) => String(x ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const name = String(c.tenantName || '').toLowerCase();
const has = (w) => name.includes(w.toLowerCase());
const maxAttempts = Number(s.maxAttempts) || 3;
const realDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && DateTime.fromISO(d).isValid;
const result = (status, reasonCode = '', extra = {}) => ({
  status,
  reasonCode,
  reasonText: reasonCode ? TEXT[reasonCode] || reasonCode : '',
  outcome: '',
  urgent: false,
  stepsDone: '[]',
  errorDetail: '',
  hang: false,
  ...extra,
});

let r;
try {
  if (has('Hang')) {
    r = result('in_progress', '', { hang: true });
  } else if (has('FailAlways')) {
    r = result('failed', 'RBIS_ERROR', { errorDetail: 'Pretend RBIS error (stand-in Performer, FailAlways)' });
  } else if (has('FailOnce') && Number(c.attempts) === 1) {
    r = result('failed', 'RBIS_ERROR', { errorDetail: 'Pretend RBIS error (stand-in Performer, FailOnce)' });
  } else if (has('Urgent')) {
    r = result('referred', 'UNABLE_TO_ADD_PARTY', { urgent: true, stepsDone: JSON.stringify(['endLiability']) });
  } else if (has('ReferOnce') && Number(c.submissions || 1) <= 1) {
    r = result('referred', 'ADDRESS_NOT_FOUND');
  } else if (has('Refer') && !has('ReferOnce')) {
    r = result('referred', 'ADDRESS_NOT_FOUND');
  } else if (c.coveredByCaseKey) {
    // Check 2: a joint row takes its result from its lead row.
    if (lead.status === 'updated') r = result('duplicate', 'SAME_TENANCY_AS_EARLIER_ROW');
    else if (lead.status === 'referred' || lead.status === 'duplicate' || (lead.status === 'failed' && Number(lead.attempts) >= maxAttempts)) r = result('referred', 'EARLIER_ROW_NOT_COMPLETED');
    else r = result('failed', 'RBIS_ERROR', { errorDetail: `Stand-in: lead row not finished (${lead.status ?? 'not found'})` });
  } else if (!realDate(c.relevantDate) || (realDate(c.startDate) && realDate(c.endDate) && c.endDate < c.startDate)) {
    r = result('referred', 'DATES_INVALID');
  } else if ((s.deathChangeReasons || ['DECEASED']).includes(c.changeReason)) {
    r = result('referred', 'DEATH_REFERRED');
  } else if (!(s.allowedChangeReasons || ['TENANCY_START', 'TENANCY_END']).includes(c.changeReason)) {
    r = result('referred', 'CHANGE_REASON_NOT_VALID');
  } else if (c.changeReason === 'TENANCY_START') {
    let joint = [];
    try { joint = JSON.parse(c.jointTenants || '[]'); } catch (e) { joint = []; }
    const people = [{ name: c.tenantName, email: c.contactEmail, phone: c.contactPhone }, ...joint];
    const withContacts = people.filter((p) => p.email || p.phone);
    const steps = ['endLiability', ...people.map((p) => 'addLiableParty:' + norm(p.name)), 'createDetail', ...withContacts.map((p) => 'setContactDetails:' + norm(p.name))];
    r = result('updated', withContacts.length ? '' : 'NO_CONTACT_DETAILS', { outcome: 'liability started', stepsDone: JSON.stringify(steps) });
  } else {
    const fwd = !!c.forwardingAddress;
    const steps = ['endLiability', 'addLiableParty:' + norm((s.landlordNames || ['landlord'])[0])];
    if (fwd) steps.push('setForwardingAddress');
    r = result('updated', '', { outcome: fwd ? 'liability ended, address saved' : 'liability ended', stepsDone: JSON.stringify(steps) });
  }
} catch (e) {
  r = result('failed', 'RBIS_ERROR', { errorDetail: 'Stand-in error: ' + e.message });
}
return [{ json: r }];
